(function () {
  function ready(fn) {
    if (document.readyState !== "loading") {
      fn();
      return;
    }
    document.addEventListener("DOMContentLoaded", fn);
  }

  ready(function () {
    var body = document.body;
    var sidebarToggle = document.getElementById("sidebarToggle");
    var sidebarToggleTop = document.getElementById("sidebarToggleTop");
    var scrollTopButton = document.querySelector(".scroll-to-top");
    var collapseLinks = document.querySelectorAll('[data-toggle="collapse"][data-target]');

    function toggleDesktopSidebar() {
      if (window.innerWidth < 992) {
        body.classList.toggle("sidebar-open");
        return;
      }
      body.classList.toggle("sidebar-toggled");
    }

    if (sidebarToggle) {
      sidebarToggle.addEventListener("click", toggleDesktopSidebar);
    }

    if (sidebarToggleTop) {
      sidebarToggleTop.addEventListener("click", toggleDesktopSidebar);
    }

    collapseLinks.forEach(function (link) {
      link.addEventListener("click", function (event) {
        event.preventDefault();
        var targetSelector = link.getAttribute("data-target");
        if (!targetSelector) {
          return;
        }
        var target = document.querySelector(targetSelector);
        if (!target) {
          return;
        }
        target.classList.toggle("show");
      });
    });

    function syncScrollButton() {
      if (!scrollTopButton) {
        return;
      }
      scrollTopButton.classList.toggle("visible", window.scrollY > 180);
    }

    window.addEventListener("scroll", syncScrollButton, { passive: true });
    syncScrollButton();

    if (scrollTopButton) {
      scrollTopButton.addEventListener("click", function (event) {
        event.preventDefault();
        window.scrollTo({ top: 0, behavior: "smooth" });
      });
    }
  });
})();
